.skill-container {
  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  color: #e0e0e0;
  width: 320px;
  border: 1px solid rgba(0, 180, 255, 0.3);
  border-radius: 4px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.skill-header {
  display: flex;
  background: rgba(0, 120, 255, 0.2);
  font-weight: bold;
  font-size: 10px;
  text-transform: uppercase;
  padding: 6px 8px;
  cursor: pointer;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  align-items: center;
}

.skill-header > div:hover {
  color: #00d2ff;
}

.col-name { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: flex; align-items: center; justify-content: space-between; }
.col-val { width: 65px; text-align: right; flex-shrink: 0; }
.col-cnt { width: 35px; text-align: right; flex-shrink: 0; }
.col-pct { width: 45px; text-align: right; flex-shrink: 0; }
.col-reset { font-size: 14px; cursor: pointer; margin-left: 5px; }
.col-reset:hover { color: #ff4444; }

.skill-list {
  max-height: 400px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 180, 255, 0.5) rgba(0, 0, 0, 0.2);
}

.skill-list::-webkit-scrollbar {
  width: 6px;
}

.skill-list::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
}

.skill-list::-webkit-scrollbar-thumb {
  background-color: rgba(0, 180, 255, 0.5);
  border-radius: 3px;
}

.skill-row {
  display: flex;
  padding: 4px 8px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
  align-items: center;
}

.skill-row:hover {
  background: rgba(0, 180, 255, 0.1);
}

.skill-row .col-name { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.skill-row .col-val { width: 65px; text-align: right; flex-shrink: 0; font-family: 'Courier New', monospace; color: #00ffaa; }
.skill-row .col-cnt { width: 35px; text-align: right; flex-shrink: 0; color: #ffcc00; font-weight: bold; }
.skill-row .col-pct { width: 45px; text-align: right; flex-shrink: 0; color: #aaa; font-size: 10px; }

.no-data {
  padding: 15px;
  text-align: center;
  font-style: italic;
  opacity: 0.5;
  font-size: 11px;
}
